-- Internal only: caller must obtain ability score, grant identities, learned book,
-- class, level and allowed editions from authoritative records, never request JSON.
create function public.terravale_validate_preparation(
 p_class text,p_level integer,p_ability_score integer,p_prepared text[],p_learned text[],p_grants text[],p_editions text[]
) returns boolean language plpgsql stable set search_path='' as $f$
declare r public.terravale_prepared_spell_rules%rowtype;
begin
 if p_ability_score is null or p_ability_score not between 1 and 30
 or p_prepared is null or p_learned is null or p_grants is null or p_editions is null
 or cardinality(p_prepared)>100 or cardinality(p_learned)>1000 or cardinality(p_grants)>100
 or array_position(p_prepared,null) is not null or array_position(p_learned,null) is not null or array_position(p_grants,null) is not null or array_position(p_editions,null) is not null
 then return false; end if;
 select * into r from public.terravale_prepared_spell_rules where class_name=p_class and character_level=p_level and not provisional;
 if not found then return false; end if;
 if cardinality(p_prepared)>greatest(1,r.preparation_base+floor((p_ability_score-10)/2.0)::integer) then return false; end if;
 if exists(select 1 from unnest(p_prepared) x(id) left join public.terravale_spell_selection_catalog s on s.id=x.id
 where s.id is null or s.level=0 or s.level>r.max_spell_level or not(s.classes ? p_class) or not(s.edition=any(p_editions))) then return false; end if;
 if (select count(distinct s.identity) from unnest(p_prepared) x(id) join public.terravale_spell_selection_catalog s on s.id=x.id)<>cardinality(p_prepared) then return false; end if;
 if exists(select 1 from public.terravale_spell_selection_catalog s join public.terravale_spell_selection_catalog g on g.identity=s.identity where s.id=any(p_prepared) and g.id=any(p_grants)) then return false; end if;
 if p_class='Wizard' and not(p_prepared<@p_learned) then return false; end if;
 return true;
end $f$;
revoke all on function public.terravale_validate_preparation(text,integer,integer,text[],text[],text[],text[]) from public,anon,authenticated;
-- Initial or earned cantrip selection, only base-class choices; feature extras handled separately.
create function public.terravale_validate_prepared_cantrips(p_class text,p_level integer,p_ids text[],p_editions text[],p_grants text[]) returns boolean language plpgsql stable set search_path='' as $f$
declare r public.terravale_prepared_spell_rules%rowtype;
begin
 if p_ids is null or p_editions is null or p_grants is null or array_position(p_ids,null) is not null or array_position(p_editions,null) is not null or array_position(p_grants,null) is not null then return false; end if;
 select * into r from public.terravale_prepared_spell_rules where class_name=p_class and character_level=p_level and not provisional;
 if not found or cardinality(p_ids)<>r.cantrip_limit then return false; end if;
 if exists(select 1 from unnest(p_ids) x(id) left join public.terravale_spell_selection_catalog s on s.id=x.id where s.id is null or s.level<>0 or not(s.classes ? p_class) or not(s.edition=any(p_editions))) then return false; end if;
 if exists(select 1 from public.terravale_spell_selection_catalog s join public.terravale_spell_selection_catalog g on g.identity=s.identity where s.id=any(p_ids) and g.id=any(p_grants)) then return false; end if;
 return (select count(distinct s.identity) from unnest(p_ids) x(id) join public.terravale_spell_selection_catalog s on s.id=x.id)=cardinality(p_ids);
end $f$;
revoke all on function public.terravale_validate_prepared_cantrips(text,integer,text[],text[],text[]) from public,anon,authenticated;
commit;
